--

CREATE FUNCTION company.inventory_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE company.inventory
    SET stock       = loaded - unloaded,
        available   = loaded - unloaded - ordered
    WHERE inventory_id = NEW.inventory_id;
    RETURN NULL;
END;
$$;


