CREATE FUNCTION company.numbering_rebuild(in_event integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE 
    i           integer; 
BEGIN
    -- clear old values
    DELETE FROM company.numbering 
    WHERE event_id = in_event; -- event include company
    -- re-index, update identity
    EXECUTE format('REINDEX TABLE company.numbering');
	EXECUTE format('SELECT coalesce(max(numbering_id), 0) + 1 FROM company.numbering') INTO i;
	EXECUTE format('ALTER TABLE company.numbering ALTER COLUMN numbering_id RESTART WITH %s', i) ;
    -- update numbering table
		company_id,
		event_id,
		event_date,
		day_part,
		current_value,
		created_at,
		created_by,
		updated_at,
		updated_by,
		object_version)
	SELECT
		company_id,
		event_id,
		stat_order_date,
		stat_order_day_part,
		max(order_number) AS current_value,
		now(),
		system.pa_current_user(),
		now(),
		system.pa_current_user(),
		0
	FROM company.order_header
	WHERE event_id = in_event
	GROUP BY company_id, event_id, stat_order_date, stat_order_day_part;
END;
$$;


