--
-- TOC entry 349 (class 1255 OID 261746)
-- Name: update_numbering_table(); Type: FUNCTION; Schema: company; Owner: pa_owner_role
--

CREATE FUNCTION company.update_numbering_table() RETURNS trigger
    LANGUAGE plpgsql
    AS $$  
DECLARE 
    num integer;
    lunch_time time;
    dinner_time time;   
BEGIN
    -- update current order number if > of the previous, create a record if not present
    num :=  (
        SELECT current_value
        FROM company.numbering
        WHERE event_id = NEW.event_id
            AND event_date = NEW.stat_order_date
            AND day_part = NEW.stat_order_day_part);  -- event include company
    IF num IS NULL THEN
            company_id,
            event_id,
            event_date,
            day_part,
            current_value) 
        VALUES (
            NEW.company_id,
            NEW.event_id,
            NEW.stat_order_date,
            NEW.stat_order_day_part,
            0);
        num := 0;
    END IF;
    IF NEW.order_number > num THEN
        UPDATE company.numbering 
        SET current_value = NEW.order_number 
        WHERE event_id = NEW.event_id
            AND event_date = NEW.stat_order_date
            AND day_part = NEW.stat_order_day_part; -- event include company
    END IF;
    RETURN NULL;
END
