--
-- TOC entry 363 (class 1255 OID 261762)
-- Name: update_company_user_date(); Type: FUNCTION; Schema: system; Owner: pa_owner_role
--

CREATE FUNCTION system.update_company_user_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    CASE TG_OP
        WHEN 'INSERT' THEN
            NEW.created_at := now();
            NEW.created_by := system.pa_current_user();
            NEW.updated_at := NEW.created_at;
            NEW.updated_by := NEW.created_by;
            NEW.object_version = 0;
            IF EXISTS(
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_schema = TG_TABLE_SCHEMA 
                    AND table_name = TG_TABLE_NAME 
                    AND column_name = 'company_id'
                ) THEN
                IF NEW.company_id IS Null THEN
                    NEW.company_id = system.pa_current_company();
                END IF;
            END IF;
        WHEN 'UPDATE' THEN
            NEW.updated_by := system.pa_current_user();
            NEW.updated_at := now();
            IF OLD.object_version = 2147483647 THEN -- avoid overflow
            	NEW.object_version = 1;
            ELSE
            	NEW.object_version = OLD.object_version + 1;
            END IF;
            -- On update don't neew to set company_id
    END CASE;
    
    RETURN NEW;
END;
$$;


