--
-- TOC entry 364 (class 1255 OID 261763)
-- Name: update_connection_history(); Type: FUNCTION; Schema: system; Owner: pa_owner_role
--

CREATE FUNCTION system.update_connection_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec system.connection_history;
BEGIN
    rec.session_id := OLD.session_id;
    rec.login_datetime := OLD.access_date;
    rec.logout_datetime := now();
    rec.db_user_name := OLD.db_user_name;
    rec.app_user_code := OLD.app_user_code;
    rec.client_name := OLD.client_name;
    rec.client_ip := OLD.client_ip;
    rec.client_port := OLD.client_port;
    rec.company_desc := (SELECT OLD.company_id::text || ' ' || left(description, 30) 
                         FROM system.company 
                         WHERE company_id = OLD.company_id);
    rec.profile_code := OLD.profile_code;
    
        session_id,
        login_datetime,
        logout_datetime,
        db_user_name,
        app_user_code,
        client_name,
        client_ip,
        client_port,
        company_desc,
        profile_code
        )
    VALUES (
        rec.session_id,
        rec.login_datetime,
        rec.logout_datetime,
        rec.db_user_name,
        rec.app_user_code,
        rec.client_name,
        rec.client_ip,
        rec.client_port,
        rec.company_desc,
        rec.profile_code
        );
    -- delelete older records
    IF system.pa_setting('clear_connection_history') IS NOT NULL THEN
        DELETE FROM system.connection_history
        WHERE logout_datetime < current_date - system.pa_setting('clear_connection_history')::int;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION system.update_connection_history() OWNER TO pa_owner_role;

