    de.description AS department,
    it.item_type,
    it.description AS item,
    ol.variants,
    (it.description || COALESCE((' '::text || ol.variants), ''::text)) AS item_with_variants,
    ol.quantity,
    ol.price,
    ol.amount
   FROM ((((((company.order_line ol
     JOIN company.order_header oh ON ((ol.order_header_id = oh.order_header_id)))
     JOIN company.event ev ON ((oh.event_id = ev.event_id)))
     JOIN company.item it ON ((ol.item_id = it.item_id)))
     JOIN company.department de ON ((it.department_id = de.department_id)))
     LEFT JOIN company.price_list pr ON ((ev.price_list_id = pr.price_list_id)))
     LEFT JOIN company.price_list_item pri ON (((pr.price_list_id = pri.price_list_id) AND (it.item_id = pri.item_id))));


