--
-- TOC entry 260 (class 1259 OID 262255)
-- Name: vw_item_availability; Type: VIEW; Schema: company; Owner: pa_owner_role
--

CREATE VIEW company.vw_item_availability AS
 SELECT e.company_id,
    e.event_id,
    e.description AS event_description,
    i.department_id,
    d.description AS department_description,
    i.item_type,
    i.item_id,
    i.description AS item_description,
    i.customer_description AS item_customer_description,
    i.is_salable,
    COALESCE(p.price, 0.00) AS price,
    COALESCE(i.pos_row, 0) AS pos_row,
    COALESCE(i.pos_column, 0) AS pos_column,
    i.normal_text_color,
    i.normal_background_color,
    i.has_inventory_control,
    i.has_delivered_control,
    i.has_variants,
    COALESCE(s.available, 0.00) AS available,
    i.is_web_available,
    i.web_sorting,
        CASE i.has_inventory_control
            WHEN (true AND (s.available > (0)::numeric)) THEN true
            WHEN false THEN true
            ELSE false
        END AS is_available
   FROM (((((company.event e
     LEFT JOIN company.item i ON ((e.company_id = i.company_id)))
     JOIN company.department d ON ((i.department_id = d.department_id)))
     LEFT JOIN company.price_list pl ON ((pl.price_list_id = e.price_list_id)))
     LEFT JOIN company.price_list_item p ON (((p.price_list_id = pl.price_list_id) AND (p.item_id = i.item_id))))
     LEFT JOIN ( SELECT s_1.event_id AS event,
            i_1.item_id AS item,
            COALESCE(s_1.available, 0.00) AS available
           FROM (company.item i_1
             LEFT JOIN ( SELECT inventory.event_id,
                    inventory.item_id,
                    inventory.available
                   FROM company.inventory) s_1 ON ((i_1.item_id = s_1.item_id)))
          WHERE (i_1.item_type = 'I'::bpchar)
        UNION
         SELECT t.event,
            i_1.item_id AS item,
            round(min((t.available / ik.quantity)), 2) AS available
           FROM ((company.item i_1
             JOIN company.item_part ik ON ((ik.item_id = i_1.item_id)))
             JOIN ( SELECT s_1.event_id AS event,
                    k.part_id AS item,
                    COALESCE(s_1.available, 0.00) AS available
                   FROM ((company.item_part k
                     JOIN company.item pi ON ((k.part_id = pi.item_id)))
                     LEFT JOIN ( SELECT inventory.event_id,
                            inventory.item_id,
                            inventory.available
                           FROM company.inventory) s_1 ON ((k.part_id = s_1.item_id)))
                  WHERE ((pi.has_inventory_control IS TRUE) AND (pi.is_obsolete IS FALSE))) t ON ((ik.part_id = t.item)))
          WHERE (i_1.item_type = 'K'::bpchar)
          GROUP BY t.event, i_1.item_id
        UNION
         SELECT s_1.event,
            i_1.item_id AS item,
            round(min((s_1.available / im.quantity)), 2) AS available
           FROM ((company.item i_1
             JOIN company.item_part im ON ((i_1.item_id = im.item_id)))
             JOIN ( SELECT s_2.event_id AS event,
                    i_2.item_id AS item,
                    COALESCE(s_2.available, 0.00) AS available
                   FROM (company.item i_2
                     LEFT JOIN ( SELECT inventory.event_id,
                            inventory.item_id,
                            inventory.available
                           FROM company.inventory) s_2 ON ((i_2.item_id = s_2.item_id)))
                  WHERE (i_2.item_type = 'I'::bpchar)
                UNION
                 SELECT t.event,
                    i_2.item_id AS item,
                    round(min((t.available / ik.quantity)), 2) AS available
                   FROM ((company.item i_2
                     JOIN company.item_part ik ON ((ik.item_id = i_2.item_id)))
                     JOIN ( SELECT s_2.event_id AS event,
                            k.part_id AS item,
                            COALESCE(s_2.available, 0.00) AS available
                           FROM ((company.item_part k
                             JOIN company.item pi ON ((k.part_id = pi.item_id)))
                             LEFT JOIN ( SELECT inventory.event_id,
                                    inventory.item_id,
                                    inventory.available
                                   FROM company.inventory) s_2 ON ((k.part_id = s_2.item_id)))
                          WHERE ((pi.has_inventory_control IS TRUE) AND (pi.is_obsolete IS FALSE))) t ON ((ik.part_id = t.item)))
                  WHERE (i_2.item_type = 'K'::bpchar)
                  GROUP BY t.event, i_2.item_id) s_1 ON ((im.part_id = s_1.item)))
          WHERE (i_1.item_type = 'M'::bpchar)
          GROUP BY s_1.event, i_1.item_id) s ON (((e.event_id = s.event) AND (i.item_id = s.item))))
  WHERE (i.is_obsolete IS FALSE);


ALTER VIEW company.vw_item_availability OWNER TO pa_owner_role;

