--
-- TOC entry 262 (class 1259 OID 262274)
-- Name: vw_order_status; Type: VIEW; Schema: company; Owner: pa_owner_role
--

CREATE VIEW company.vw_order_status AS
 SELECT oh.company_id,
    c.description AS company_description,
    oh.event_id,
    e.description AS event_description,
    oh.order_header_id,
    oh.order_date_time,
    oh.order_date,
    oh.order_time,
    oh.stat_order_date,
    oh.stat_order_day_part,
    oh.order_number,
    oh.delivery,
    oh.table_num AS table_number,
    oh.customer_name,
    oh.covers,
    oh.status,
    oh.fulfillment_date,
    oh.cash_desk,
    oh.created_by AS user_ins,
    oh.is_from_web AS from_web,
    od.dep1 AS department1,
    od.fulfill1 AS fulfillment1,
    od.dep2 AS department2,
    od.fulfill2 AS fulfillment2,
    od.dep3 AS department3,
    od.fulfill3 AS fulfillment3,
    od.dep4 AS department4,
    od.fulfill4 AS fulfillment4,
    od.dep5 AS department5,
    od.fulfill5 AS fulfillment5,
    od.dep6 AS department6,
    od.fulfill6 AS fulfillment6
   FROM (((company.order_header oh
     JOIN system.company c ON ((oh.company_id = c.company_id)))
     JOIN company.event e ON ((oh.event_id = e.event_id)))
     JOIN ( SELECT i.order_header_id,
            max(
                CASE i.dn
                    WHEN 1 THEN i.department
                    ELSE NULL::text
                END) AS dep1,
            max(
                CASE i.dn
                    WHEN 1 THEN i.fulfillment_date
                    ELSE NULL::timestamp with time zone
                END) AS fulfill1,
            max(
                CASE i.dn
                    WHEN 2 THEN i.department
                    ELSE NULL::text
                END) AS dep2,
            max(
                CASE i.dn
                    WHEN 2 THEN i.fulfillment_date
                    ELSE NULL::timestamp with time zone
                END) AS fulfill2,
            max(
                CASE i.dn
                    WHEN 3 THEN i.department
                    ELSE NULL::text
                END) AS dep3,
            max(
                CASE i.dn
                    WHEN 3 THEN i.fulfillment_date
                    ELSE NULL::timestamp with time zone
                END) AS fulfill3,
            max(
                CASE i.dn
                    WHEN 4 THEN i.department
                    ELSE NULL::text
                END) AS dep4,
            max(
                CASE i.dn
                    WHEN 4 THEN i.fulfillment_date
                    ELSE NULL::timestamp with time zone
                END) AS fulfill4,
            max(
                CASE i.dn
                    WHEN 5 THEN i.department
                    ELSE NULL::text
                END) AS dep5,
            max(
                CASE i.dn
                    WHEN 5 THEN i.fulfillment_date
                    ELSE NULL::timestamp with time zone
                END) AS fulfill5,
            max(
                CASE i.dn
                    WHEN 6 THEN i.department
                    ELSE NULL::text
                END) AS dep6,
            max(
                CASE i.dn
                    WHEN 6 THEN i.fulfillment_date
                    ELSE NULL::timestamp with time zone
                END) AS fulfill6
           FROM ( SELECT ohd.order_header_id,
                    row_number() OVER (PARTITION BY ohd.order_header_id ORDER BY ohd.order_header_id, d.sorting) AS dn,
                    d.description AS department,
                    ohd.fulfillment_date
                   FROM (company.order_header_department ohd
                     JOIN company.department d ON ((ohd.department_id = d.department_id)))) i
          GROUP BY i.order_header_id) od ON ((od.order_header_id = oh.order_header_id)));


ALTER VIEW company.vw_order_status OWNER TO pa_owner_role;

