--
-- TOC entry 263 (class 1259 OID 262279)
-- Name: vw_sales_summary; Type: VIEW; Schema: company; Owner: pa_owner_role
--

CREATE VIEW company.vw_sales_summary AS
 SELECT oh.company_id,
    oh.event_id,
    ev.description AS event_description,
    ev.start_date,
    ev.end_date,
    oh.stat_order_date AS order_date,
    count(
        CASE
            WHEN (oh.stat_order_day_part = 'L'::bpchar) THEN oh.order_header_id
            ELSE NULL::bigint
        END) AS num_orders_lunch,
    count(
        CASE
            WHEN (oh.stat_order_day_part = 'D'::bpchar) THEN oh.order_header_id
            ELSE NULL::bigint
        END) AS num_orders_dinner,
    sum(
        CASE
            WHEN (oh.stat_order_day_part = 'L'::bpchar) THEN oh.covers
            ELSE 0
        END) AS num_covers_lunch,
    sum(
        CASE
            WHEN (oh.stat_order_day_part = 'D'::bpchar) THEN oh.covers
            ELSE 0
        END) AS num_covers_dinner,
    sum(
        CASE
            WHEN ((oh.delivery = 'A'::bpchar) AND (oh.stat_order_day_part = 'L'::bpchar)) THEN oh.total_amount
            ELSE (0)::numeric
        END) AS take_away_lunch,
    sum(
        CASE
            WHEN ((oh.delivery = 'A'::bpchar) AND (oh.stat_order_day_part = 'D'::bpchar)) THEN oh.total_amount
            ELSE (0)::numeric
        END) AS take_away_dinner,
    sum(
        CASE
            WHEN ((oh.delivery = 'T'::bpchar) AND (oh.stat_order_day_part = 'L'::bpchar)) THEN oh.total_amount
            ELSE (0)::numeric
        END) AS table_lunch,
    sum(
        CASE
            WHEN ((oh.delivery = 'T'::bpchar) AND (oh.stat_order_day_part = 'D'::bpchar)) THEN oh.total_amount
            ELSE (0)::numeric
        END) AS table_dinner,
    sum(
        CASE
            WHEN (oh.stat_order_day_part = 'L'::bpchar) THEN oh.total_amount
            ELSE (0)::numeric
        END) AS amount_lunch,
    sum(
        CASE
            WHEN (oh.stat_order_day_part = 'D'::bpchar) THEN oh.total_amount
            ELSE (0)::numeric
        END) AS amount_dinner,
    sum(
        CASE
            WHEN (oh.stat_order_day_part = 'L'::bpchar) THEN oh.discount
            ELSE (0)::numeric
        END) AS discount_lunch,
    sum(
        CASE
            WHEN (oh.stat_order_day_part = 'D'::bpchar) THEN oh.discount
            ELSE (0)::numeric
        END) AS discount_dinner,
    sum(
        CASE
            WHEN ((oh.is_electronic_payment IS TRUE) AND (oh.stat_order_day_part = 'L'::bpchar)) THEN (oh.total_amount - oh.discount)
            ELSE (0)::numeric
        END) AS electronic_lunch,
    sum(
        CASE
            WHEN ((oh.is_electronic_payment IS TRUE) AND (oh.stat_order_day_part = 'D'::bpchar)) THEN (oh.total_amount - oh.discount)
            ELSE (0)::numeric
        END) AS electronic_dinner,
    sum(
        CASE
            WHEN ((oh.is_electronic_payment IS FALSE) AND (oh.stat_order_day_part = 'L'::bpchar)) THEN (oh.total_amount - oh.discount)
            ELSE (0)::numeric
        END) AS cash_lunch,
    sum(
        CASE
            WHEN ((oh.is_electronic_payment IS FALSE) AND (oh.stat_order_day_part = 'D'::bpchar)) THEN (oh.total_amount - oh.discount)
            ELSE (0)::numeric
        END) AS cash_dinner,
    sum(
        CASE
            WHEN (oh.stat_order_day_part = 'L'::bpchar) THEN (oh.total_amount - oh.discount)
            ELSE (0)::numeric
        END) AS total_lunch,
    sum(
        CASE
            WHEN (oh.stat_order_day_part = 'D'::bpchar) THEN (oh.total_amount - oh.discount)
            ELSE (0)::numeric
        END) AS total_dinner
   FROM (company.order_header oh
     JOIN company.event ev ON ((oh.event_id = ev.event_id)))
  GROUP BY oh.company_id, oh.event_id, ev.description, ev.start_date, ev.end_date, oh.stat_order_date
  ORDER BY oh.company_id, ev.description, oh.stat_order_date;


