n\t\t\t<line x1="66.0" y1="3.0" x2="66.0" y2="19.0" lineWidth="2.0" style="SolidLine"/>\n\t\t\t<special left="1.0" top="0.5" width="65.0" height="17.0" color="grey" fontWeight="ExtraBold" fontItalic="True"  textAlign="AlignHCenter">appName</special>\n\t\t\t<special left="0.5" top="0.0" width="65.0" height="17.0" color="black" fontWeight="ExtraBold" fontItalic="True"  textAlign="AlignHCenter">appName</special>\n\t\t\t<special left="0.0" top="11.0" width="65.0" height="17.0" fontSize="4" textAlign="AlignHCenter">appEmail</special>\n\t\t\t<!-- Page number -->\n\t\t\t<rectangle left="80.0" top="0.0" width="400.0" height="17.0" lineWidth="0.5" xRadius="0.0" yRadius="0.0"/>\n\t\t\t<label left="235.0" top="3.0" width="40.0" height="17.0">Pagina:</label>\n\t\t\t<special left="275.0" top="3.0" width="35.0" height="17.0" textAlign="AlignLeft">pageNumber</special>\n\t\t\t<!-- Application Name and reference -->\n\t\t\t<rectangle left="495.0" top="0.0" width="65.0" height="17.0" lineWidth="0.5" xRadius="0.0" yRadius="0.0"/>\n\t\t\t<line x1="498.0" y1="18.0" x2="561.0" y2="18.0" lineWidth="2.0" style="SolidLine"/>\n\t\t\t<line x1="561.0" y1="3.0" x2="561.0" y2="19.0" lineWidth="2.0" style="SolidLine"/>\n\t\t\t<special left="495.0" top="0.5" width="65.0" height="17.0" color="grey" fontWeight="ExtraBold" fontItalic="True" textAlign="AlignHCenter">appName</special>\n\t\t\t<special left="494.5" top="0.0" width="65.0" height="17.0" color="black" fontWeight="ExtraBold" fontItalic="True" textAlign="AlignHCenter">appName</special>\n\t\t\t<special left="495.0" top="11.0" width="65.0" height="17.0" fontSize="4" textAlign="AlignHCenter">appEmail</special>\n        </band>\n    </pageFooter>\n</report>	f
2026-09-02 22:17:33.808+02	sistema	2026-09-02 22:17:33.808+02	sistema	0	21	order_A4ST_customer_copy	en_US	ORDER_CUSTOMER	Order report (A4 stripe) customer copy	<report version="1.0">\n    <options>\n        <documentName type="str">Order report customer copy</documentName>\n\t\t<lang type="str">EN</lang>\n        <orientation type="str">Portrait</orientation>\n        <unit type="str">Point</unit>\n        <pageSize type="str">A4</pageSize>\n        <topMargin type="float">15.0</topMargin>\n        <bottomMargin type="float">15.0</bottomMargin>\n        <leftMargin type="float">15.0</leftMargin>\n        <rightMargin type="float">15.0</rightMargin>\n        <fontFamily type="str">Arial</fontFamily>\n        <fontSize type="int">7</fontSize>\n    </options>\n    <query>\n        <select><!-- Select query without where and order by clause -->\nSELECT \n\tev.description,\n\tev.image,\n\toh.order_header_id,\n\toh.order_number,\n\toh.order_date,\n\toh.order_time,\n\toh.created_by,\n\toh.cash_desk,\n\toh.delivery,\n\toh.table_num,\n\toh.covers,\n\toh.customer_name,\n\toh.total_amount,\n\toh.discount,\n\toh.total_amount - oh.discount AS to_be_paid,\n\toh.cash,\n\tit.customer_description || ' ' || coalesce(ol.variants, ''),\n\tol.quantity,\n\tol.price,\n\tol.amount\nFROM order_header oh\nJOIN order_line ol ON oh.order_header_id = ol.order_header_id\nJOIN event ev ON oh.event_id = ev.event_id\nJOIN item it ON ol.item_id = it.item_id;\n        </select>\n\t\t<where>oh.company_id = system.pa_current_company()</where>\n        <conditions><!-- some fields of the select query used for the where and order by clause creation -->\n            <condition code="order_id" description="Order Id" type="int">oh.order_header_id</condition>\n        </conditions>\n    </query>\n    <columns><!-- Must have a columnNumber/fieldName for every column of the dataset -->\n        <fieldName>event_description</fieldName>\n\t\t<fieldName>event_image</fieldName>\n\t\t<fieldName>order_id</fieldName>\n\t\t<fieldName>order_number</fieldName>\n        <fieldName>order_date</fieldName>\n        <fieldName>order_time</fieldName>\n        <fieldName>user</fieldName>\n\t\t<fieldName>cash_desk</fieldName>\n\t\t<fieldName>delivery</fieldName>\n        <fieldName>table_number</fieldName>\n        <fieldName>covers</fieldName>\n\t\t<fieldName>customer_name</fieldName>\n\t\t<fieldName>total_amount</fieldName>\n        <fieldName>discount</fieldName>\n\t\t<fieldName>to_be_paid</fieldName>\n        <fieldName>cash</fieldName>\n        <fieldName>item</fieldName>\n        <fieldName>quantity</fieldName>\n        <fieldName>price</fieldName>\n\t\t<fieldName>amount</fieldName>\n    </columns>\n    <parameters>\n    </parameters>\n    <pageHeader>\n        <band height="50.0">\n\t\t\t<special left="140.0" top="0.0" width="260.0" height="22.0" fontWeight="Bold" fontItalic="True" fontSize="10" textAlign="AlignHCenter">companyDescription</special>\n\t\t\t<field left="140.0" top="27.0" width="260.0" height="18.0" fontWeight="Bold" fontItalic="True" fontSize="10" textAlign="AlignHCenter">event_description</field>\n\t\t</band>\n    </pageHeader>\n\t<groups>\n        <!-- groups are nested -->\n        <group field="order_id" reverse="False">\n\t\t\t<groupHeader>\n\t\t\t\t<band height="120.0" canGrow="True">\n\t\t\t\t\t<execute trigger="Before">\n# set order information\nband[1].value = 'Order ' + str(record['order_number']) + '  date ' + record['order_date'].toString('dd/MM/yyyy')\nband[2].value = 'Time ' + record['order_time'].toString('hh:mm:ss')\n\n# set table/covers/name base on delivery type\nif record['delivery'] == 'T':\n\ttext = 'Table: ' + str(record['table_number'] or '') + '  Covers: ' + str(record['covers'] or '')\n\tif record['customer_name']:\n\t\ttext += '  Name: ' + record['customer_name']\n\tband[5].value = text\nelse:\n\tband[5].value = 'EXPORT Name: ' + (record['customer_name'] or '')\n\t\t\t\t\t</execute>\n\t\t\t\t\t<field left="140.0" top="5.0" width="80.0" height="80.0">event_image</field>\n           \t\t\t<label left="230.0" top="10.0" width="180.0" height="24.0" color="darkBlue" fontWeight="Bold" fontItalic="True" fontSize="10" textAlign="AlignLeft">replaced text</label> <!-- order number and date -->\n\t\t\t\t\t<label left="230.0" top="33.0" width="180.0" height="24.0" color="darkBlue" fontWeight="Bold" fontItalic="True" fontSize="10" textAlign="AlignLeft">replaced text</label> <!-- order time -->\n\t\t\t\t\t<label left="230.0" top="60.0" width="60.0" height="15.0">Cash desk:</label>\n\t\t\t\t\t<field left="290.0" top="60.0" width="110.0" height="15.0" textAlign="AlignLeft">cash_desk</field>\n\t\t\t\t\t<label left="230.0" top="80.0" width="170.0" height="15.0">replaced text</label> <!-- order table and covers -->\n\t\t\t\t\t<!-- detail header -->\n            \t\t<label left="140.0" top="100.0" width="120.0" height="15.0" fontWeight="Bold">Item</label>\n           \t\t\t<label left="260.0" top="100.0" width="40.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Q.ty</label>\n            \t\t<label left="300.0" top="100.0" width="50.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Price</label>\n            \t\t<label left="350.0" top="100.0" width="50.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Amount</label>\n\t\t\t\t\t<line x1="140.0" y1="118.0" x2="400.0" y2="118.0" lineWidth="1.0"/>\n\t\t\t\t</band>\n\t\t\t</groupHeader>\n\t\t\t<groupFooter>\n\t\t\t\t<band height="80.0" newPageAfter="True" restartPageNumber="True">\n\t\t\t\t\t<execute trigger="Before">\n# print total or total/discount/amount due\nif record['discount'] == 0.0:\n\tband[3].isVisible = False\n\tband[4].isVisible = False\n\tband[5].isVisible = False\n\tband[6].isVisible = False\nelse:\n\tband[3].isVisible = True\n\tband[4].isVisible = True\n\tband[5].isVisible = True\n\tband[6].isVisible = True\n\t\t\t\t\t</execute>\n\t\t\t\t\t<line x1="140.0" y1="5.0" x2="400.0" y2="5.0" lineWidth="1.0"/>\n\t\t\t\t\t<label left="220.0" top="30.0" width="90.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight">Total amount:</label>\n\t\t\t\t\t<field left="310.0" top="30.0" width="70.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight" format="currency">total_amount</field>\n\t\t\t\t\t<label left="220.0" top="45.0" width="90.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight">Discount:</label>\n\t\t\t\t\t<field left="310.0" top="45.0" width="70.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight" format="currency">discount</field>\n\t\t\t\t\t<label left="220.0" top="60.0" width="90.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight">To be paid:</label>\n\t\t\t\t\t<field left="310.0" top="60.0" width="70.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight" format="currency">to_be_paid</field>\n\t\t\t\t</band>\n\t\t\t</groupFooter>\n        </group>\n    </groups>\n    <details>\n        <band height="17.0" canGrow="True" isVisible="True">\n\t\t\t<field left="140.0" top="2" width="120.0" height="15.0" canGrow="True" textAlign="AlignLeft">item</field>\n\t\t\t<field left="260.0" top="2" width="40.0" height="15.0" textAlign="AlignRight">quantity</field>\n            <field left="300.0" top="2" width="50.0" height="15.0" textAlign="AlignRight" format="currency">price</field>\n\t\t\t<field left="350.0" top="2" width="50.0" height="15.0" textAlign="AlignRight" format="currency">amount</field>\n        </band>\n    </details>\n    <pageFooter>\n    </pageFooter>\n</report>	f
