\n\t\t<fieldName>order_number</fieldName>\n        <fieldName>order_date</fieldName>\n        <fieldName>order_time</fieldName>\n        <fieldName>user</fieldName>\n\t\t<fieldName>cash_desk</fieldName>\n\t\t<fieldName>delivery</fieldName>\n        <fieldName>table_number</fieldName>\n        <fieldName>covers</fieldName>\n\t\t<fieldName>customer_name</fieldName>\n\t\t<fieldName>total_amount</fieldName>\n        <fieldName>discount</fieldName>\n\t\t<fieldName>to_be_paid</fieldName>\n        <fieldName>cash</fieldName>\n        <fieldName>item</fieldName>\n        <fieldName>quantity</fieldName>\n        <fieldName>price</fieldName>\n\t\t<fieldName>amount</fieldName>\n    </columns>\n    <parameters>\n    </parameters>\n    <pageHeader>\n        <band height="50.0">\n\t\t\t<special left="140.0" top="0.0" width="260.0" height="22.0" fontWeight="Bold" fontItalic="True" fontSize="10" textAlign="AlignHCenter">companyDescription</special>\n\t\t\t<field left="140.0" top="27.0" width="260.0" height="18.0" fontWeight="Bold" fontItalic="True" fontSize="10" textAlign="AlignHCenter">event_description</field>\n\t\t</band>\n    </pageHeader>\n\t<groups>\n        <!-- groups are nested -->\n        <group field="order_id" reverse="False">\n\t\t\t<groupHeader>\n\t\t\t\t<band height="120.0" canGrow="True">\n\t\t\t\t\t<execute trigger="Before">\n# set order information\nband[1].value = 'Ordine ' + str(record['order_number']) + '  data ' + record['order_date'].toString('dd/MM/yyyy')\nband[2].value = 'Ora ' + record['order_time'].toString('hh:mm:ss')\n\n# set table/covers/name base on delivery type\nif record['delivery'] == 'T':\n\ttext = 'Tavolo: ' + str(record['table_number'] or '') + '  Coperti: ' + str(record['covers'] or '')\n\tif record['customer_name']:\n\t\ttext += '  Nome: ' + record['customer_name']\n\tband[5].value = text\nelse:\n\tband[5].value = 'ASPORTO Nome: ' + (record['customer_name'] or '')\n\t\t\t\t\t</execute>\n\t\t\t\t\t<field left="140.0" top="5.0" width="80.0" height="80.0">event_image</field>\n           \t\t\t<label left="230.0" top="10.0" width="180.0" height="24.0" color="darkBlue" fontWeight="Bold" fontItalic="True" fontSize="10" textAlign="AlignLeft">replaced text</label> <!-- order number and date -->\n\t\t\t\t\t<label left="230.0" top="33.0" width="180.0" height="24.0" color="darkBlue" fontWeight="Bold" fontItalic="True" fontSize="10" textAlign="AlignLeft">replaced text</label> <!-- order time -->\n\t\t\t\t\t<label left="230.0" top="60.0" width="60.0" height="15.0">Cassa:</label>\n\t\t\t\t\t<field left="290.0" top="60.0" width="110.0" height="15.0" textAlign="AlignLeft">cash_desk</field>\n\t\t\t\t\t<label left="230.0" top="80.0" width="170.0" height="15.0">replaced text</label> <!-- order table and covers -->\n\t\t\t\t\t<!-- detail header -->\n            \t\t<label left="140.0" top="100.0" width="120.0" height="15.0" fontWeight="Bold">Articolo</label>\n           \t\t\t<label left="260.0" top="100.0" width="40.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Q.tà</label>\n            \t\t<label left="300.0" top="100.0" width="50.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Prezzo</label>\n            \t\t<label left="350.0" top="100.0" width="50.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Importo</label>\n\t\t\t\t\t<line x1="140.0" y1="118.0" x2="400.0" y2="118.0" lineWidth="1.0"/>\n\t\t\t\t</band>\n\t\t\t</groupHeader>\n\t\t\t<groupFooter>\n\t\t\t\t<band height="80.0" newPageAfter="True" restartPageNumber="True">\n\t\t\t\t\t<execute trigger="Before">\n# print total or total/discount/amount due\nif record['discount'] == 0.0:\n\tband[3].isVisible = False\n\tband[4].isVisible = False\n\tband[5].isVisible = False\n\tband[6].isVisible = False\nelse:\n\tband[3].isVisible = True\n\tband[4].isVisible = True\n\tband[5].isVisible = True\n\tband[6].isVisible = True\n\t\t\t\t\t</execute>\n\t\t\t\t\t<line x1="140.0" y1="5.0" x2="400.0" y2="5.0" lineWidth="1.0"/>\n\t\t\t\t\t<label left="200.0" top="30.0" width="110.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight">Importo totale:</label>\n\t\t\t\t\t<field left="310.0" top="30.0" width="70.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight" format="currency">total_amount</field>\n\t\t\t\t\t<label left="220.0" top="45.0" width="90.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight">Sconto:</label>\n\t\t\t\t\t<field left="310.0" top="45.0" width="70.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight" format="currency">discount</field>\n\t\t\t\t\t<label left="220.0" top="60.0" width="90.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight">A pagare:</label>\n\t\t\t\t\t<field left="310.0" top="60.0" width="70.0" height="15.0" fontWeight="Bold" fontSize="10" textAlign="AlignRight" format="currency">to_be_paid</field>\n\t\t\t\t</band>\n\t\t\t</groupFooter>\n        </group>\n    </groups>\n    <details>\n        <band height="17.0" canGrow="True" isVisible="True">\n\t\t\t<field left="140.0" top="2" width="120.0" height="15.0" canGrow="True" textAlign="AlignLeft">item</field>\n\t\t\t<field left="260.0" top="2" width="40.0" height="15.0" textAlign="AlignRight" format="quantity">quantity</field>\n            <field left="300.0" top="2" width="50.0" height="15.0" textAlign="AlignRight" format="currency">price</field>\n\t\t\t<field left="350.0" top="2" width="50.0" height="15.0" textAlign="AlignRight" format="currency">amount</field>\n        </band>\n    </details>\n    <pageFooter>\n    </pageFooter>\n</report>	f
