 code="order_id" description="Order Id" type="int">oh.order_header_id</condition>\n        </conditions>\n\t\t<orderBy>it.sorting</orderBy>\n    </query>\n    <columns><!-- Must have a columnNumber/fieldName for every column of the dataset -->\n        <fieldName>event_description</fieldName>\n\t\t<fieldName>event_image</fieldName>\n\t\t<fieldName>order_id</fieldName>\n\t\t<fieldName>order_number</fieldName>\n        <fieldName>order_date</fieldName>\n        <fieldName>order_time</fieldName>\n        <fieldName>user</fieldName>\n\t\t<fieldName>cash_desk</fieldName>\n\t\t<fieldName>delivery</fieldName>\n        <fieldName>table_number</fieldName>\n        <fieldName>covers</fieldName>\n\t\t<fieldName>customer_name</fieldName>\n\t\t<fieldName>total_amount</fieldName>\n        <fieldName>discount</fieldName>\n\t\t<fieldName>amount_due</fieldName>\n        <fieldName>cash</fieldName>\n\t\t<fieldName>change</fieldName>\n        <fieldName>item</fieldName>\n        <fieldName>quantity</fieldName>\n        <fieldName>price</fieldName>\n\t\t<fieldName>amount</fieldName>\n    </columns>\n    <parameters>\n    </parameters>\n    <pageHeader>\n        <band height="100.0">\n\t\t\t<special left="0.0" top="0.0" width="227.0" height="18.0" fontSize="10" fontItalic="True" textAlign="AlignHCenter">companyDescription</special>\n\t\t\t<field left="70.0" top="20.0" width="70.0" height="60.0">event_image</field>\n\t\t\t<field left="0.0" top="80.0" width="227.0" height="18.0" fontSize="10" fontWeight="Bold" fontItalic="True" textAlign="AlignHCenter">event_description</field>\n\t\t</band>\n    </pageHeader>\n\t<groups>\n        <!-- groups are nested -->\n        <group field="order_id" reverse="False">\n\t\t\t<groupHeader>\n\t\t\t\t<band height="80.0">\n\t\t\t\t\t<execute trigger="Before">\n# set order information\nband[0].value = f"Ordine {record['order_number'] or ''} Data {record['order_date'].toString('dd/MM/yyyy')} ore {record['order_time'].toString('hh:mm:ss')}"\n\n# set table/covers base on delivery type\nif record['delivery'] == 'T':\n\tband[1].value = f"Tavolo: {str(record['table_number'] or '')} Coperti: {str(record['covers'] or '')}"\nelse:\n\tband[1].value = 'TAKE-AWAY'\n# set name\nband[2].value = f"Nome: {record['customer_name'] or ''}"\n# set cash desk and user\nband[3].value = f"Cassa: {record['cash_desk'] or ''}/{record['user'] or ''}"\n\t\t\t\t\t</execute>\n           \t\t\t<label left="0.0" top="0.0" width="227.0" height="15.0" fontWeight="Bold" textAlign="AlignLeft">replaced text</label><!-- order number date -->\n\t\t\t\t\t<label left="0.0" top="15.0" width="227.0" height="15.0" textAlign="AlignLeft">replaced text</label><!-- table -->\n\t\t\t\t\t<label left="0.0" top="30.0" width="227.0" height="15.0" textAlign="AlignLeft">replaced text</label><!-- name -->\n\t\t\t\t\t<label left="0.0" top="45.0" width="227.0" height="15.0" textAlign="AlignLeft">replaced text</label><!-- cash desk and user -->\n\t\t\t\t\t<!-- detail header -->\n            \t\t<label left="0.0" top="62.0" width="105.0" height="15.0" fontWeight="Bold" textAlign="AlignLeft">Articolo</label>\n           \t\t\t<label left="105.0" top="62.0" width="25.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Q.tà</label>\n            \t\t<label left="130.0" top="62.0" width="50.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Prezzo</label>\n            \t\t<label left="180.0" top="62.0" width="47.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Importo</label>\n\t\t\t\t\t<line x1="0.0" y1="80.0" x2="227.0" y2="80.0" lineWidth="1.0"/>\n\t\t\t\t</band>\n\t\t\t</groupHeader>\n\t\t\t<groupFooter>\n\t\t\t\t<band height="3" isVisible="True">\n\t\t\t\t\t<line x1="0.0" y1="3.0" x2="227.0" y2="3.0" lineWidth="1.0"/>\n\t\t\t\t</band>\n\t\t\t\t<band height="25.0" canGrow="True">\n\t\t\t\t\t<label left="0.0" top="10.0" width="160.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Importo totale:</label>\n\t\t\t\t\t<field left="160.0" top="10.0" width="65.0" height="15.0" fontWeight="Bold" textAlign="AlignRight" format="currency">total_amount</field>\n\t\t\t\t</band>\n\t\t\t\t<band height="30.0" canGrow="True">\n\t\t\t\t\t<execute trigger="Before">\n# hide if no discount\nif record['discount'] == 0.0:\n\tband.isVisible = False\n\t\t\t\t\t</execute>\n\t\t\t\t\t<label left="0.0" top="0.0" width="160.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Sconto:</label>\n\t\t\t\t\t<field left="160.0" top="0.0" width="65.0" height="15.0" fontWeight="Bold" textAlign="AlignRight" format="currency">discount</field>\n\t\t\t\t\t<label left="0.0" top="15.0" width="160.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">A pagare:</label>\n\t\t\t\t\t<field left="160.0" top="15.0" width="65.0" height="15.0" fontWeight="Bold" textAlign="AlignRight" format="currency">amount_due</field>\n\t\t\t\t</band>\n\t\t\t\t<band height="30.0" canGrow="True">\n\t\t\t\t\t<execute trigger="Before">\n# hide if no change\nif record['change'] == 0.0:\n\tband.isVisible = False\n\t\t\t\t\t</execute>\n\t\t\t\t\t<label left="0.0" top="0.0" width="160.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Contante:</label>\n\t\t\t\t\t<field left="160.0" top="0.0" width="65.0" height="15.0" fontWeight="Bold" textAlign="AlignRight" format="currency">cash</field>\n\t\t\t\t\t<label left="0.0" top="15.0" width="160.0" height="15.0" fontWeight="Bold" textAlign="AlignRight">Resto:</label>\n\t\t\t\t\t<field left="160.0" top="15.0" width="65.0" height="15.0" fontWeight="Bold" textAlign="AlignRight" format="currency">change</field>\n\t\t\t\t</band>\n\t\t\t\t<band height="35.0">\n\t\t\t\t\t<!-- Application Name and reference -->\n\t\t\t\t\t<label left="0.0" top="20.0" width="227.0" height="15.0" fontItalic="True" fontSize="8" textAlign="AlignLeft">pySagra - info@paolodestefani.it</label>\n\t\t\t\t</band>\n\t\t\t</groupFooter>\n        </group>\n    </groups>\n    <details>\n        <band height="15.0" canGrow="True" isVisible="True">\n\t\t\t<field