2026-09-02 22:17:33.826+02	sistema	2026-09-02 22:17:33.826+02	sistema	0	31	order_TM20_department_copy	en_US	ORDER_DEPARTMENT	Order report (TM20) department copy	<report version="1.0">\n    <options>\n        <documentName type="str">Order report department copy</documentName>\n\t\t<lang type="str">EN</lang>\n        <orientation type="str">Portrait</orientation>\n        <unit type="str">Point</unit>\n        <pageSize type="str">Custom</pageSize>\n\t\t<pageWidth type="int">227</pageWidth><!-- size must be set in printer driver -->\n\t\t<pageHeight type="int">842</pageHeight><!-- size must be set in printer driver -->\n\t\t<ignoreWarningOnSetPageLayout type="bool">True</ignoreWarningOnSetPageLayout>\n        <topMargin type="float">0.0</topMargin>\n        <bottomMargin type="float">0.0</bottomMargin>\n        <leftMargin type="float">0.0</leftMargin>\n        <rightMargin type="float">0.0</rightMargin>\n        <fontFamily type="str">Arial</fontFamily>\n        <fontSize type="int">7</fontSize>\n    </options>\n    <query>\n        <select><!-- Select query without where and order by clause -->\nSELECT \n\tev.description,\n\tohd.order_header_department_id AS ohd_id,\n    oh.order_header_id,\n\toh.order_number,\n\toh.order_date,\n\toh.order_time,\n\toh.created_by,\n\toh.cash_desk,\n\toh.delivery,\n\tohd.department_id,\n\tdep.description,\n\toh.table_num,\n\toh.covers,\n\toh.customer_name,\n\tohd.note,\n    ohd.other_departments,\n\tit.description || ' ' || coalesce(olid.variants, ''),\n\tolid.quantity\nFROM order_header_department ohd\nJOIN order_header oh ON ohd.order_header_id = oh.order_header_id\nJOIN event ev ON oh.event_id = ev.event_id\nJOIN order_line_department olid ON ohd.order_header_department_id = olid.order_header_department_id\nJOIN department dep ON ohd.department_id = dep.department_id\nJOIN item it ON olid.item_id = it.item_id\n        </select>\n\t\t<where>oh.company_id = system.pa_current_company()</where>\n        <conditions><!-- some fields of the select query used for the where and order by clause creation -->\n            <condition code="order_id" description="Order Id" type="int">oh.order_header_id</condition>\n\t\t\t<condition code="department_id" description="Department Id" type="int">ohd.department_id</condition>\n        </conditions>\n    </query>\n    <columns><!-- Must have a columnNumber/fieldName for every column of the dataset -->\n\t\t<fieldName>event_description</fieldName>\n\t\t<fieldName>order_dep_id</fieldName>\n\t\t<fieldName>order_id</fieldName>\n        <fieldName>order_number</fieldName>\n        <fieldName>order_date</fieldName>\n        <fieldName>order_time</fieldName>\n        <fieldName>user</fieldName>\n\t\t<fieldName>cash_desk</fieldName>\n        <fieldName>delivery</fieldName>\n\t\t<fieldName>department_id</fieldName>\n\t\t<fieldName>department_description</fieldName>\n\t\t<fieldName>table_number</fieldName>\n        <fieldName>covers</fieldName>\n\t\t<fieldName>customer_name</fieldName>\n        <fieldName>department_note</fieldName>\n\t\t<fieldName>other_departments</fieldName>\n\t\t<fieldName>item</fieldName>\n        <fieldName>quantity</fieldName>\n    </columns>\n    <parameters>\n    </parameters>\n    <pageHeader>\n         <band height="40.0">\n\t\t\t<field left="0.0" top="0.0" width="227.0" height="15.0" fontSize="10" fontWeight="Bold" fontItalic="True" textAlign="AlignLeft">event_description</field>\n\t\t\t<special left="0.0" top="15.0" width="227.0" height="15.0" fontSize="10" fontItalic="True" textAlign="AlignLeft">companyDescription</special>\n\t\t</band>\n    </pageHeader>\n\t<groups>\n        <!-- groups are nested -->\n         <group field="order_id" reverse="False">\n\t\t</group>\n\t\t<group field="department_id" reverse="False">\n\t\t\t<groupHeader>\n\t\t\t\t<band height="95.0" canGrow="True">\n\t\t\t\t\t<execute trigger="Before">\n# set order information\nband[0].value = f"Order {record['order_number'] or ''} Date {record['order_date'].toString('MM.dd.yyyy')} Time {record['order_time'].toString('hh:mm:ss')}"\n\n# set cash desk and user\nband[1].value = f"Cash desk: {record['cash_desk'] or ''}/{record['user'] or ''}"\n\n# set table/covers/name base on delivery type\nif record['delivery'] == 'T':\n\tband[2].value = f"Table: {record['table_number'] or ''} Seats: {record['covers'] or ''} Name: {record['customer_name'] or ''}"\nelse:\n\tband[2].value = f"TAKE-AWAY Name: {record['customer_name']}"\n\n# set other departments if any\nif record['other_departments']:\n\tband[5].value = f"Other: {record['other_departments'] or ''}"\nelse:\n\tband[5].value = "No other department"\n\n\t\t\t\t\t</execute>\n           \t\t\t<label left="0.0" top="0.0" width="227.0" height="15.0" fontWeight="Bold" textAlign="AlignLeft">replaced text</label> <!-- order reference -->\n\t\t\t\t\t<label left="0.0" top="15.0" width="147.0" height="15.0" textAlign="AlignLeft">replaced text</label> <!-- cash desk and user -->\n\t\t\t\t\t<label left="0.0" top="30.0" width="227.0" height="15.0">replaced text</label> <!-- table/covers/name -->\n\t\t\t\t\t<label left="0.0" top="45.0" width="60.0" height="15.0" fontWeight="Bold">Copy:</label>\n\t\t\t\t\t<field left="60.0" top="45.0" width="167.0" height="15.0" fontWeight="Bold">department_description</field> <!-- department copy label -->\n\t\t\t\t\t<label left="0.0" top="60.0" width="227.0" height="15.0">replaced text</label> <!-- other departments -->\n\t\t\t\t\t<field isVisible="True" left="0.0" top="75.0" width="227.0" height="40.0" fontName="Archon Code 39 Barcode" fontSize="36" barcodeType="Code39" format="{:09}" textAlign="AlignHCenter">order_dep_id</field> <!-- barcode -->\n\t\t\t\t\t<!-- detail header -->\n           \t\t\t<label left="0.0" top="90.0" width="40.0" height="15.0" fontWeight="Bold">Q.ty</label>\n\t\t\t\t\t<label left="40.0" top="90.0" width="150.0" height="15.0" fontWeight="Bold">Item</label>\n\t\t\t\t\t<line x1="0.0" y1="108.0" x2="227.0" y2="108.0" lineWidth="1.0"/>\n\t\t\t\t</band>\n\t\t\t</groupHeader>\n\t\t\t<groupFooter>\n\t\t\t\t<band height="0.0" canGrow="True">\n\t\t\t\t\t<line x1="0.0" y1="5.0" x2="227.0" y2="5.0" lineWidth="1.0"/>\n\t\t\t\t\t<field left="0.0" top="10.0" width="80.0" height="10.0" fontSize="8" fontWeight="Bold" textAlign="AlignLeft" canGrow="True">department_note</field>\n\t\t\t\t</band>\n\t\t\t\t<band height="60.0" canGrow="False">\n\t\t\t\t\t<label left="0.0" top="10.0" width="40.0" height="20.0">Order:</label>\n\t\t\t\t\t<field left="42.0" top="10.0" width="38.0" height="20.0">order_number</field>\n\t\t\t\t\t<label left="80.0" top="10.0" width="40.0" height="20.0">Table:</label>\n\t\t\t\t\t<field left="120.0" top="10.0" width="87.0" height="20.0">table_number</field>\n\t\t\t\t\t<label left="0.0" top="40.0" width="40.0" height="20.0">Order:</label>\n\t\t\t\t\t<field left="42.0" top="40.0" width="38.0" height="20.0">order_number</field>\n\t\t\t\t\t<label left="80.0" top="40.0" width="40.0" height="20.0">Table:</label>\n\t\t\t\t\t<field left="120.0" top="40.0" width="87.0" height="20.0">table_number</field>\n\t\t\t\t</band>\n\t\t\t</groupFooter>\n\t\t</group>\n    </groups>\n    <details>\n       <band height="15.0" canGrow="True" isVisible="True">\n\t\t\t<field left="0.0" top="0.0" width="40.0" height="15.0" format="{0:.0f}">quantity</field>\n\t\t\t<field left="40.0" top="0.0" width="187.0" height="15.0" canGrow="True">item</field>\n        </band>\n    </details>\n    <pageFooter>\n    </pageFooter>\n</report>	f
