 the select query used for the where and order by clause creation -->\n            <condition code="order_id" description="Order Id" type="int">oh.order_header_id</condition>\n\t\t\t<condition code="department_id" description="Department Id" type="int">ohd.department_id</condition>\n        </conditions>\n    </query>\n    <columns><!-- Must have a columnNumber/fieldName for every column of the dataset -->\n\t\t<fieldName>event_description</fieldName>\n\t\t<fieldName>order_dep_id</fieldName>\n\t\t<fieldName>order_id</fieldName>\n        <fieldName>order_number</fieldName>\n        <fieldName>order_date</fieldName>\n        <fieldName>order_time</fieldName>\n        <fieldName>user</fieldName>\n\t\t<fieldName>cash_desk</fieldName>\n        <fieldName>delivery</fieldName>\n\t\t<fieldName>department_id</fieldName>\n\t\t<fieldName>department_description</fieldName>\n\t\t<fieldName>table_number</fieldName>\n        <fieldName>covers</fieldName>\n\t\t<fieldName>customer_name</fieldName>\n        <fieldName>department_note</fieldName>\n\t\t<fieldName>other_departments</fieldName>\n\t\t<fieldName>item</fieldName>\n        <fieldName>quantity</fieldName>\n    </columns>\n    <parameters>\n    </parameters>\n    <pageHeader>\n         <band height="40.0">\n\t\t\t<field left="0.0" top="0.0" width="227.0" height="15.0" fontSize="10" fontWeight="Bold" fontItalic="True" textAlign="AlignLeft">event_description</field>\n\t\t\t<special left="0.0" top="15.0" width="227.0" height="15.0" fontSize="10" fontItalic="True" textAlign="AlignLeft">companyDescription</special>\n\t\t</band>\n    </pageHeader>\n\t<groups>\n        <!-- groups are nested -->\n         <group field="order_id" reverse="False">\n\t\t</group>\n\t\t<group field="department_id" reverse="False">\n\t\t\t<groupHeader>\n\t\t\t\t<band height="95.0" canGrow="True">\n\t\t\t\t\t<execute trigger="Before">\n# set order information\nband[0].value = f"Ordine {record['order_number'] or ''} Data {record['order_date'].toString('dd/MM