taset -->\n        <fieldName>event_description</fieldName>\n\t\t<fieldName>event_image</fieldName>\n\t\t<fieldName>order_id</fieldName>\n\t\t<fieldName>order_number</fieldName>\n        <fieldName>order_date</fieldName>\n        <fieldName>order_time</fieldName>\n        <fieldName>user</fieldName>\n\t\t<fieldName>cash_desk</fieldName>\n\t\t<fieldName>delivery</fieldName>\n        <fieldName>table_number</fieldName>\n        <fieldName>covers</fieldName>\n\t\t<fieldName>customer_name</fieldName>\n\t\t<fieldName>total_amount</fieldName>\n        <fieldName>discount</fieldName>\n\t\t<fieldName>amount_due</fieldName>\n        <fieldName>cash</fieldName>\n\t\t<fieldName>change</fieldName>\n\t\t<fieldName>department_sorting</fieldName>\n\t\t<fieldName>item_sorting</fieldName>\n        <fieldName>item</fieldName>\n        <fieldName>quantity</fieldName>\n        <fieldName>price</fieldName>\n\t\t<fieldName>amount</fieldName>\n    </columns>\n    <parameters>\n    </parameters>\n\t<pageBackground>\n        <field left="140.0" top="0.0" width="100.0" height="100.0">event_image</field>\n    </pageBackground>\n    <pageHeader>\n        <band height="90.0">\n\t\t\t<special left="0.0" top="0.0" width="380.0" height="30.0" fontSize="10" textAlign="AlignHCenter">companyDescription</special>\n\t\t\t<!-- outline effect for event description -->\n\t\t\t<field left="1.0" top="31.0" width="380.0" height="60.0" fontName="Comic Sans MS" fontWeight="Bold" fontItalic="True" fontSize="18" textAlign="AlignHCenter" color="lightgray" >event_description</field>\n\t\t\t<field left="0.0" top="30.0" width="380.0" height="60.0" fontName="Comic Sans MS" fontWeight="Bold" fontItalic="True" fontSize="18" textAlign="AlignHCenter" >event_description</field>\n\t\t</band>\n    </pageHeader>\n\t<groups>\n        <!-- groups are nested -->\n        <group field="order_id" reverse="False">\n\t\t\t<groupHeader>\n\t\t\t\t<band height="25.0" canGrow="False">\n\t\t\t\t\t<execute trigger="Before">\n# set order 