nts</condition>\n\t\t\t<condition code="inventory_control" description="Controllo esistenza" type="bool">it.has_inventory_control</condition>\n\t\t\t<condition code="delivered_control" description="Controllo consegnato" type="bool">it.has_delivered_control</condition>\n\t\t\t<condition code="kit_part" description="Componente kiy" type="bool">it.is_kit_part</condition>\n\t\t\t<condition code="menu_part" description="Componente menù" type="bool">it.is_menu_part</condition>\n\t\t\t<condition code="web_available" description="Disponibile sul web" type="bool">it.is_web_available</condition>\n\t\t\t<condition code="is_obsolete" description="Obsoleto" type="bool">it.is_obsolete</condition>\n       \t</conditions>\n    </query>\n    <columns><!-- Must have a fieldName for every column of the dataset -->\n\t\t<fieldName>department</fieldName>\n\t\t<fieldName>depsort</fieldName>\n        <fieldName>item_type</fieldName>\n        <fieldName>item</fieldName>\n\t\t<fieldName>description</fieldName>\n\t\t<fieldName>customer_description</fieldName>\n        <fieldName>is_salable</fieldName>\n        <fieldName>sorting</fieldName>\n\t\t<fieldName>pos_row</fieldName>\n\t\t<fieldName>pos_column</fieldName>\n\t\t<fieldName>has_variants</fieldName>\n\t\t<fieldName>has_inventory_control</fieldName>\n\t\t<fieldName>has_delivered_control</fieldName>\n\t\t<fieldName>is_kit_part</fieldName>\n\t\t<fieldName>is_menu_part</fieldName>\n\t\t<fieldName>is_web_available</fieldName>\n\t\t<fieldName>web_sorting</fieldName>\n\t\t<fieldName>is_obsolete</fieldName>\n    </columns>\n    <pageHeader>\n        <band height="50.0">\n\t\t\t<label left="0.0" top="0.0" width="50.0" height="15.0">Azienda:</label>\n\t\t\t<special left="50.0" top="0.0" width="465.0" height="15.0">companyDescription</special>\n\t\t\t<label left="490.0" top="0.0" width="25.0" height="15.0">Data:</label>\n\t\t\t<special left="525.0" top="0.0" width="35.0" height="15.0" textAlign="AlignRight">printDate</special>\n\t\t\t<rectangle le