2026-09-02 22:17:33.802+02	sistema	2026-09-11 21:20:47.77+02	sistema	1	18	item_detail	it_IT	ITEM	Stampa elenco articoli dettagliata	<report version="1.0">\n    <options>\n        <documentName type="str">Stampa elenco articoli dettagliata</documentName>\n\t\t<lang type="str">IT</lang>\n        <orientation type="str">Portrait</orientation>\n        <unit type="str">Point</unit>\n        <pageSize type="str">A4</pageSize>\n        <topMargin type="float">15.0</topMargin>\n        <bottomMargin type="float">15.0</bottomMargin>\n        <leftMargin type="float">15.0</leftMargin>\n        <rightMargin type="float">15.0</rightMargin>\n        <fontFamily type="str">Arial</fontFamily>\n        <fontSize type="int">7</fontSize>\n    </options>\n    <query>\n        <select><!-- Select query without where and order by clause -->\nWITH cte AS (\n-- item\nSELECT\n\tit.company_id \t\t\t\tAS company,\n\tit.item_id \t\t\t\t\tAS item,\n\t0 \t\t\t\t\t\t\tAS row_type,\n\tdp.description \t\t\t\tAS department_description,\n\tdp.sorting\t\t\t\t\tAS depsort,\n    it.item_type \t\t\t\tAS item_type,\n    it.description \t\t\t\tAS item_description,\n    it.customer_description \tAS item_customer_description,\n    it.is_salable \t\t\t\tAS salable,\n    it.sorting \t\t\t\t\tAS sorting,\n    it.pos_row \t\t\t\t\tAS pos_row,\n    it.pos_column \t\t\t\tAS pos_column,\n    it.has_variants \t\t\tAS variants,\n    it.has_inventory_control \tAS inventory_control,\n    it.has_delivered_control \tAS delivered_control,\n    it.is_kit_part \t\t\t\tAS kit_part,\n    it.is_menu_part \t\t\tAS menu_part,\n    it.is_web_available \t\tAS web_available,\n    it.web_sorting \t\t\t\tAS web_sorting,\n    it.is_obsolete \t\t\t\tAS obsolete,\n\tNull \t\t\t\t\t\tAS variant_description,\n\t0.0 \t\t\t\t\t\tAS variant_price_delta,\n\tNull \t\t\t\t\t\tAS kit_part_description,\n\t0 \t\t\t\t\t\t\tAS kit_part_quantity,\n\tNull \t\t\t\t\t\tAS menu_part_description,\n\t0 \t\t\t\t\t\t\tAS menu_part_quantity,\n\tNull \t\t\t\t\t\tAS price_list_description,\n\t0.0 \t\t\t\t\t\tAS price_list_price\nFROM item it\nJOIN department dp ON it.department_id = dp.department_id\nUNION\n-- variants\nSELECT  \n\tit.company_id \t\t\t\tAS company,\n\tiv.item_id \t\t\t\t\tAS item,\n\t1 \t\t\t\t\t\t\tAS row_type,\n    dp.description \t\t\t\tAS department_description,\n\tdp.sorting\t\t\t\t\tAS depsort,\n\tNull \t\t\t\t\t\tAS item_type,\n    it.description\t\t\t\tAS item_description,\n    Null \t\t\t\t\t\tAS item_customer_description,\n    Null \t\t\t\t\t\tAS salable,\n    Null \t\t\t\t\t\tAS sorting,\n    Null \t\t\t\t\t\tAS pos_row,\n    Null \t\t\t\t\t\tAS pos_column,\n    Null \t\t\t\t\t\tAS variants,\n    Null \t\t\t\t\t\tAS inventory_control,\n    Null \t\t\t\t\t\tAS delivered_control,\n    Null \t\t\t\t\t\tAS kit_part,\n    Null \t\t\t\t\t\tAS menu_part,\n    Null \t\t\t\t\t\tAS web_available,\n    Null \t\t\t\t\t\tAS web_sorting,\n    Null \t\t\t\t\t\tAS obsolete,\n\tiv.variant_description \t\tAS variant_description,\n\tiv.price_delta \t\t\t\tAS price_delta,\n\tNull \t\t\t\t\t\tAS kit_part_description,\n\t0 \t\t\t\t\t\t\tAS kit_part_quantity,\n\tNull \t\t\t\t\t\tAS menu_part_description,\n\t0 \t\t\t\t\t\t\tAS menu_part_quantity,\n\tNull \t\t\t\t\t\tAS price_list_description,\n\t0.0 \t\t\t\t\t\tAS price_list_price\nFROM item_variant iv\nJOIN item it ON iv.item_id = it.item_id\nJOIN department dp ON it.department_id = dp.department_id\nUNION\n-- kit part\nSELECT  \n\tit.company_id \t\t\t\tAS company,\n\tkp.item_id \t\t\t\t\tAS item,\n\t2 \t\t\t\t\t\t\tAS row_type,\n    dp.description \t\t\t\tAS department_description,\n\tdp.sorting\t\t\t\t\tAS depsort,\n\tNull \t\t\t\t\t\tAS item_type,\n    it.description\t\t\t\tAS item_description,\n    Null \t\t\t\t\t\tAS item_customer_description,\n    Null \t\t\t\t\t\tAS salable,\n    Null \t\t\t\t\t\tAS sorting,\n    Null \t\t\t\t\t\tAS pos_row,\n    Null \t\t\t\t\t\tAS pos_column,\n    Null \t\t\t\t\t\tAS variants,\n    Null \t\t\t\t\t\tAS inventory_control,\n    Null \t\t\t\t\t\tAS delivered_control,\n    Null \t\t\t\t\t\tAS kit_part,\n    Null \t\t\t\t\t\tAS menu_part,\n    Null \t\t\t\t\t\tAS web_available,\n    Null \t\t\t\t\t\tAS web_sorting,\n    Null \t\t\t\t\t\tAS obsolete,\n\tNull \t\t\t\t\t\tAS variant_description,\n\t0.0 \t\t\t\t\t\tAS price_delta,\n\tkpi.description \t\t\tAS kit_part_description,\n\tkp.quantity \t\t\t\tAS kit_part_quantity,\n\tNull \t\t\t\t\t\tAS menu_part_description,\n\t0 \t\t\t\t\t\t\tAS menu_part_quantity,\n\tNull \t\t\t\t\t\tAS price_list_description,\n\t0.0 \t\t\t\t\t\tAS price_list_price\nFROM item_part kp\nJOIN item kpi ON kp.part_id = kpi.item_id\nJOIN item it ON kp.item_id = it.item_id\nJOIN department dp ON it.department_id = dp.department_id\nWHERE kp.item_type = 'K'\nUNION\n-- menu part\nSELECT \n\tit.company_id \t\t\t\tAS company,\n\tmp.item_id \t\t\t\t\tAS item,\n\t3 \t\t\t\t\t\t\tAS row_type,\n    dp.description \t\t\t\tAS department_description,\n\tdp.sorting\t\t\t\t\tAS depsort,\n\tNull \t\t\t\t\t\tAS item_type,\n    it.description\t\t\t\tAS item_description,\n    Null \t\t\t\t\t\tAS item_customer_description,\n    Null \t\t\t\t\t\tAS salable,\n    Null \t\t\t\t\t\tAS sorting,\n    Null \t\t\t\t\t\tAS pos_row,\n    Null \t\t\t\t\t\tAS pos_column,\n    Null \t\t\t\t\t\tAS variants,\n    Null \t\t\t\t\t\tAS inventory_control,\n    Null \t\t\t\t\t\tAS delivered_control,\n    Null \t\t\t\t\t\tAS kit_part,\n    Null \t\t\t\t\t\tAS menu_part,\n    Null \t\t\t\t\t\tAS web_available,\n    Null \t\t\t\t\t\tAS web_sorting,\n    Null \t\t\t\t\t\tAS obsolete,\n\tNull \t\t\t\t\t\tAS variant_description,\n\t0.0 \t\t\t\t\t\tAS price_delta,\n\tNull \t\t\t\t\t\tAS kit_part_description,\n\t0 \t\t\t\t\t\t\tAS kit_part_quantity,\n\tmpi.description \t\t\tAS menu_part_description,\n\tmp.quantity \t\t\t\tAS menu_part_quantity,\n\tNull \t\t\t\t\t\tAS price_list_description,\n\t0.0 \t\t\t\t\t\tAS price_list_price\nFROM item_part mp\nJOIN item mpi ON mp.part_id = mpi.item_id\nJOIN item it ON mp.item_id = it.item_id\nJOIN department dp ON it.department_id = dp.department_id\nWHERE mp.item_type = 'M'\nUNION\n-- price list\nSELECT  \n\tit.company_id \t\t\t\tAS company,\n\tpld.item_id \t\t\t\tAS item,\n\t4 \t\t\t\t\t\t\tAS row_type,\n    dp.description \t\t\t\tAS department_description,\n\tdp.sorting\t\t\t\t\tAS depsort,\n\tNull \t\t\t\t\t\tAS item_type,\n    it.description\t\t\t\tAS item_description,\n    Null \t\t\t\t\t\tAS item_customer_description,\n    Null \t\t\t\t\t\tAS salable,\n    Null \t\t\t\t\t\tAS sorting,\n    Null \t\t\t\t\t\tAS pos_row,\n    Null \t\t\t\t\t\tAS pos_column,\n    Null \t\t\t\t\t\tAS variants,\n    Null \t\t\t\t\t\tAS inventory_control,\n    Null \t\t\t\t\t\tAS delivered_control,\n    Null \t\t\t\t\t\tAS kit_part,\n    Null \t\t\t\t\t\tAS menu_part,\n    Null \t\t\t\t\t\tAS web_available,\n    Null \t\t\t\t\t\tAS web_sorting,\n    Null \t\t\t\t\t\tAS obsolete,\n\tNull \t\t\t\t\t\tAS variant_description,\n\t0.0 \t\t\t\t\t\tAS price_delta,\n\tNull \t\t\t\t\t\tAS kit_part_description,\n\t0 \t\t\t\t\t\t\tAS kit_part_quantity,\n\tNull \t\t\t\t\t\tAS menu_part_description,\n\t0 \t\t\t\t\t\t\tAS menu_part_quantity,\n\tpl.description \t\t\t\tAS price_list_description,\n\tpld.price \t\t\t\t\tAS price_list_price\nFROM price_list_item pld\nJOIN price_list pl ON pl.price_list_id = pld.price_list_id\nJOIN item it ON pld.item_id = it.item_id\nJOIN department dp ON it.department_id = dp.department_id)\nSELECT * FROM cte\n\t\t</select>\n\t\t<where>cte.company = system.pa_current_company()</where>\n        <conditions><!-- some fields of the select query used for the where and order by clause creation -->\n\t\t\t<condition code="department" description="Reparto" type="str">cte.department_description</condition>\n\t\t\t<condition code="item_type" description="Tipo articolo" type="str">cte.item_type</condition>\n            <condition code="description" description="Descrizionr articolo" type="str">cte.item_description</condition>\n\t\t\t<condition code="salable" description="Vendibile" type="bool">cte.salable</condition>\n\t\t\t<condition code="variants" description="Varianti" type="bool">cte.variants</condition>\n\t\t\t<condition code="inventory_control" description="Controllo esistenza" type="bool">cte.inventory_control</condition>\n\t\t\t<condition code="delivered_control" description="Controllo consegnato" type="bool">cte.delivered_control</condition>\n\t\t\t<condition code="kit_part" description="Componente kit" type="bool">cte.kit_part</condition>\n\t\t\t<condition code="menu_part" description="Componente menu" type="bool">cte.menu_part</condition>\n\t\t\t<condition code="web_available" description="Disponibile sul Web" type="bool">cte.web_available</condition>\n\t\t\t<condition code="is_obsolete" description="Obsoleto" type="bool">cte.obsolete</condition>\n       \t</conditions>\n    </query>\n    <columns><!-- Must have a fieldName for every column of the dataset -->\n\t\t<fieldName>company</fieldName>\n\t\t<fieldName>item</fieldName>\n\t\t<fieldName>row_type</fieldName>\n\t\t<fieldName>department</fieldName>\n\t\t<fieldName>depsort</fieldName>\n       \t<fieldName>item_type</fieldName>\n\t\t<fieldName>item_description</fieldName>\n\t\t<fieldName>item_customer_description</fieldName>\n       \t<fieldName>is_salable</fieldName>\n       \t<fieldName>sorting</fieldName>\n\t\t<fieldName>pos_row</fieldName>\n\t\t<fieldName>pos_column</fieldName>\n\t\t<fieldName>has_variants</fieldName>\n\t\t<fieldName>has_inventory_control</fieldName>\n\t\t<fieldName>has_delivered_control</fieldName>\n\t\t<fieldName>is_kit_part</fieldName>\n\t\t<fieldName>is_menu_part</fieldName>\n\t\t<fieldName>is_web_available</fieldName>\n\t\t<fieldName>web_sorting</fieldName>\n\t\t<fieldName>is_obsolete</fieldName>\n\t\t<fieldName>variant_description</fieldName>\n\t\t<fieldName>variant_price_delta</fieldName>\n\t\t<fieldName>kit_part_description</fieldName>\n\t\t<fieldName>kit_part_quantity</fieldName>\n\t\t<fieldName>menu_part_description</