2026-09-02 22:17:33.859+02	sistema	2026-09-02 22:17:33.859+02	sistema	0	48	statistic_sales	it_IT	STATISTICS	Stampa statistiche di vendita	<report version="1.0">\n    <options>\n        <documentName type="str">Statistiche di vendita</documentName>\n\t\t<lang type="str">IT</lang>\n        <orientation type="str">Portrait</orientation>\n        <unit type="str">Point</unit>\n        <pageSize type="str">A4</pageSize>\n        <topMargin type="float">10.0</topMargin>\n        <bottomMargin type="float">10.0</bottomMargin>\n        <leftMargin type="float">10.0</leftMargin>\n        <rightMargin type="float">10.0</rightMargin>\n        <fontFamily type="str">Arial</fontFamily>\n        <fontSize type="int">7</fontSize>\n    </options>\n    <query>\n        <select><!-- Select query without where and order by clause -->\nSELECT \n\toh.event_id\t\t\t\t\tAS event_id, \n\tev.description \t\t\t\tAS event_description,\n\tev.start_date\t\t\t\tAS start_date,\n\tev.end_date\t\t\t\t\tAS end_date,\n    oh.stat_order_date\t\t\tAS stat_order_date,\n\toh.order_number\t\t\t\tAS order_number,\n\toh.order_date\t\t\t\tAS order_date,\n\toh.order_time\t\t\t\tAS order_time,\n\tit.department_id\t\t\tAS department_id,\n    dp.description \t\t\t\tAS department_description,\n\tdp.sorting\t\t\t\t\tAS dep_sort,\n    ol.item_id\t\t\t\t\tAS item_id,\n    it.description \t\t\t\tAS item_description,\n\tol.variants\t\t\t\t\tAS variants,\n\tit.has_inventory_control \tAS inventory_control,\n\tit.has_delivered_control \tAS delivered_control,\n\tCASE \n\t\tWHEN oh.stat_order_day_part = 'L' THEN ol.quantity\n\t\tELSE 0\n\tEND\t\t\t\t\t\t\tAS quantity_lunch,\n\tCASE \n\t\tWHEN oh.stat_order_day_part = 'D' THEN ol.quantity\n\t\tELSE 0\n\tEND\t\t\t\t\t\t\tAS quantity_dinner,\n    ol.quantity \t\t\t\tAS quantity,\n\tCASE \n\t\tWHEN oh.stat_order_day_part = 'L' THEN ol.amount\n\t\tELSE 0\n\tEND\t \t\t\t\t\t\tAS amount_lunch,\n\tCASE \n\t\tWHEN oh.stat_order_day_part = 'D' THEN ol.amount\n\t\tELSE 0\n\tEND\t\t\t \t\t\t\tAS amount_dinner,\n    ol.amount \t\t\t\t\tAS amount\nFROM order_line ol\nJOIN order_header oh ON oh.order_header_id = ol.order_header_id\nJOIN event ev ON oh.event_id = ev.event_id\nJOIN item it ON ol.item_id = it.item_id\nJOIN department dp ON it.department_id = dp.department_id\n        </select>\n\t\t<where>oh.company_id = system.pa_current_company()</where>\n        <conditions><!-- some fields of the select query used for the where and order by clause creation -->\n\t\t\t<condition code="event_id" description="Evento" type="int">oh.event_id</condition>\n       \t\t<condition code="event_description" description="Descrizione evento" type="str">ev.description</condition>\n\t\t\t<condition code="stat_order_date" description="Giorno" type="date">oh.stat_order_date</condition>\n\t\t\t<condition code="department_description" description="Reparto" type="str">dp.description</condition>\n\t\t\t<condition code="item" description="Articolo" type="int">ol.item_id</condition>\n\t\t\t<condition code="item_description" description="Descrizione articolo" type="str">it.description</condition>\n\t\t\t<condition code="inventory_control" description="Controllo inventario" type="bool">it.has_inventory_control</condition>\n\t\t\t<condition code="delivered_control" description="Controllo consegnato" type="bool">it.has_delivered_control</condition>\n\t\t\t<condition code="quantity" description="Quantità" type="int">ol.quantity</condition>\n\t\t\t<condition code="amount" description="Importo" type="float">ol.amount</condition>\n        </conditions>\n    </query>\n    <columns><!-- Must have a columnNumber/fieldName for every column of the dataset --> \n        <fieldName>event_id</fieldName>\n\t\t<fieldName>event_description</fieldName>\n\t\t<fieldName>start_date</fieldName>\n\t\t<fieldName>end_date</fieldName>\n        <fieldName>stat_order_date</fieldName>\n\t\t<fieldName>order_number</fieldName>\n\t\t<fieldName>order_date</fieldName>\n\t\t<fieldName>order_time</fieldName>\n\t\t<fieldName>department_id</fieldName>\n\t\t<fieldName>department_description</fieldName>\n\t\t<fieldName>dep_sort</fieldName>\n\t\t<fieldName>item_id</fieldName>\n\t\t<fieldName>item_description</fieldName>\n\t\t<fieldName>variants</fieldName>\n\t\t<fieldName>inventory_control</fieldName>\n\t\t<fieldName>delivered_control</fieldName>\n\t\t<fieldName>quantity_lunch</fieldName>\n\t\t<fieldName>quantity_dinner</fieldName>\n\t\t<fieldName>quantity</fieldName>\n\t\t<fieldName>amount_lunch</fieldName>\n\t\t<fieldName>amount_dinner</fieldName>\n\t\t<fieldName>amount</fieldName>\n    </columns>\n\t<sorting> \n\t\t<sort field="order_time"/>\n\t</sorting>\n    <parameters>\n\t\t<parameter type="list" id="printLevel" default="1" items="1:Data|2:Data/Reparto|3:Data/Reparto/Articolo|4:Data/Reparto/Articolo/Riga d'ordine">Grouping level</parameter>\n    </parameters>\n    <pageHeader>\n        <band height="50.0">\n\t\t\t<label left="0.0" top="0.0" width="50.0" height="15.0">Azienda:</label>\n\t\t\t<special left="50.0" top="0.0" width="465.0" height="15.0">companyDescription</special>\n\t\t\t<label left="490.0" top="0.0" width="25.0" height="15.0">Data:</label>\n\t\t\t<special left="525.0" top="0.0" width="35.0" height="15.0" textAlign="AlignRight">printDate</special>\n\t\t\t<rectangle left="0.0" top="15.0" width="560.0" height="20.0" lineWidth="0.5" xRadius="0.0" yRadius="0.0"/>\n\t\t\t<line x1="3.0" y1="36.0" x2="561.0" y2="36.0" lineWidth="2.0" style="SolidLine"/>\n\t\t\t<line x1="561.0" y1="18.0" x2="561.0" y2="37.0" lineWidth="2.0" style="SolidLine"/>\n\t\t\t<label left="0.0" top="18.0" width="550.0" height="15.0" color="black" fontWeight="Bold" fontItalic="True" fontSize="10" textAlign="AlignHCenter">STATISTICHE DI VENDITA</label>\n\t\t</band>\n\t\t<band height="20">\n\t\t\t<label left="0.0" top="0.0" width="50.0" height="20.0" fontWeight="Bold">Evento:</label>\n\t\t\t<field left="50.0" top="0.0" width="270.0" height="20.0">event_description</field>\n\t\t\t<label left=